  const endX = slotXFor(span.startSlot + span.slotCount - 1) + DEPT_WIDTH
  const headX = (startX + endX) / 2 - LEADER_WIDTH / 2
  deptHeadXMap.set(span.deptId, headX)
}

const rfNodes: Node[] = []
const rfEdges: Edge[] = []

// Row 0 — Yash centered over the cluster of dept-head card positions.
if (yash) {
  const { emoji, cleanName } = extractEmoji(yash.name)
  const headXs = Array.from(deptHeadXMap.values())
  let rexX: number
  if (headXs.length > 0) {
    // Center Yash on the midpoint of (leftmost head, rightmost head + width)
    const minHeadX = Math.min(...headXs)
    const maxHeadX = Math.max(...headXs)
    rexX = (minHeadX + maxHeadX + LEADER_WIDTH) / 2 - LEADER_WIDTH / 2
  } else {
    rexX = (canvasWidth - LEADER_WIDTH) / 2
  }
  rfNodes.push({
    id: yash.id,
    type: 'orgLeader',
    position: { x: rexX, y: rexY },
    // Explicit width/height — MiniMap reads these directly to draw the
    // node rect. Without them MiniMap waits on DOM measurement and
    // can render zero-size nodes mid-fitView.
    width: LEADER_WIDTH,
    height: LEADER_HEIGHT,
    data: {
      id: yash.id,
      name: cleanName,
      emoji,
      title: yash.title,
      model: yash.model,
      tier: yash.tier,
      phaseColor: yash.departmentColor || yash.phaseColor,
      description: yash.description,
      dimmed: false,
      avatar: yash.avatar ?? null,
      gender: yash.gender ?? null,
      departmentColor: yash.departmentColor ?? null,
      level: yash.level ?? null,
      levelTitle: yash.levelTitle ?? null,
      yearsOfExperience: yash.yearsOfExperience ?? null,
      status: yash.status,
      activeTaskCount: yash.activeTaskCount ?? 0,
      maxConcurrentTasks: yash.maxConcurrentTasks ?? 3,
      loadStatus: yash.loadStatus ?? 'free',
      successRate: yash.successRate ?? null,
    } satisfies LeaderNodeData,
  })
}

// Row 1 + Row 2 — render the plan.
// Track dept → list of column nodeIds for VP edge routing.
const deptColNodeIds = new Map<string, string[]>()

for (const entry of plan) {
  const span = deptSlotMap.get(entry.dept.id)!
  const colHeight = entryHeight(entry)

  // X: subdept entries place at startSlot+gridCol; dept entries at startSlot
  const slotIdx = entry.kind === 'subdept'
    ? span.startSlot + entry.gridCol
    : span.startSlot
  const colX = slotXFor(slotIdx)

  // Y: subdept entries with gridRow > 0 stack below row 0 (with vertical gap)
  const rowOffsets = denseRowYMap.get(entry.dept.id)
  const colY = entry.kind === 'subdept' && rowOffsets
    ? deptColsY + rowOffsets[entry.gridRow]
    : deptColsY

  const nodeId = entry.kind === 'subdept'
    ? `dept-${entry.dept.id}-${entry.subDeptId}`
    : `dept-${entry.dept.id}`

  rfNodes.push({
    id: nodeId,
    type: 'orgDept',
    position: { x: colX, y: colY },
    width: DEPT_WIDTH,
    height: colHeight,
    data: {
      phase: entry.dept.id,
      phaseLabel: entry.label,
      phaseColor: entry.deptColor,
      members: entry.members,
      // Only the dept-kind column shows internal sub-dept group headers;
      // when split, each sub-dept IS the column so headers are redundant.
      subDeptGroups: entry.kind === 'dept' ? entry.subDeptGroups : undefined,
      width: DEPT_WIDTH,
      height: colHeight,
      dimmed: false,
    } satisfies DepartmentNodeData,
  })

  const list = deptColNodeIds.get(entry.dept.id) || []
  list.push(nodeId)
  deptColNodeIds.set(entry.dept.id, list)
}

// Step 2: render Row-1 dept-head card per dept (centered over its slot span)
// + edges from Yash → head, and head → each col it owns.
for (const span of deptSlots) {
  const deptEntry = plan.find(e => e.dept.id === span.deptId)
  if (!deptEntry) continue
  const dept = deptEntry.dept
  const head = dept.head

  if (head) {
    const { emoji, cleanName } = extractEmoji(head.name)
    const headX = deptHeadXMap.get(span.deptId) ?? slotXFor(span.startSlot)

    rfNodes.push({
      id: head.id,
      type: 'orgLeader',
      position: { x: headX, y: deptHeadsY },
      width: LEADER_WIDTH,
      height: LEADER_HEIGHT,
      data: {
        id: head.id,
        name: cleanName,
        emoji,
        title: head.title,
        model: head.model,
        tier: head.tier,

          phaseColor: head.departmentColor || head.phaseColor,
          description: head.description,
          dimmed: false,
          avatar: head.avatar ?? null,
          gender: head.gender ?? null,
          departmentColor: head.departmentColor ?? null,
          level: head.level ?? null,
          levelTitle: head.levelTitle ?? null,
          yearsOfExperience: head.yearsOfExperience ?? null,
          status: head.status,
          activeTaskCount: head.activeTaskCount ?? 0,
          maxConcurrentTasks: head.maxConcurrentTasks ?? 3,
          loadStatus: head.loadStatus ?? 'free',
          successRate: head.successRate ?? null,
        } satisfies LeaderNodeData,
      })

      // Yash → dept head (top-down trunk line, neutral text color)
      if (yash && head.id !== yash.id) {
        rfEdges.push({
          id: `e-${yash.id}-${head.id}`,
          source: yash.id,
          target: head.id,
          type: 'step',
          pathOptions: { offset: 24, borderRadius: 0 },
          style: { stroke: 'var(--color-text)', strokeWidth: 1.75, opacity: 0.7 },
        } as Edge)
      }
    }

    // Edges: head → each Row-2 column belonging to this dept (covers split
    // sub-cols too so dense depts get edges fanning out to each grid cell).
    const edgeSource = head?.id || yash?.id
    const colNodeIds = deptColNodeIds.get(span.deptId) || []
    if (edgeSource) {
      for (const colNodeId of colNodeIds) {
        rfEdges.push({
          id: `e-${edgeSource}-${colNodeId}`,
          source: edgeSource,
          target: colNodeId,
          type: 'step',
          pathOptions: { offset: 12, borderRadius: 0 },
          style: {
            stroke: dept.color,
            strokeWidth: 2,
            opacity: head ? 0.7 : 0.35,
            strokeDasharray: head ? undefined : '4 4',
          },
        } as Edge)
      }
    }
  }

  // ── Mentor edges (secondaryReportsTo) ─────────────────────────────────────
  // Draws a dashed purple edge between dept columns when an agent in column A
  // is mentored by an agent in a DIFFERENT column. Same-column mentorships
  // (e.g. dato → pod-b-db, both in engineering) are already visible inside
  // the column tree + the clickable ↗ pill, so we skip those to avoid
  // intra-column line spaghetti.
  const seenMentorEdge = new Set<string>()
  for (const node of allNodes) {
    if (!node.secondaryReportsTo) continue
    const mentor = byId.get(node.secondaryReportsTo)
    if (!mentor) continue
    const menteeDept = node.department || null
    const mentorDept = mentor.department || null
    if (!menteeDept || !mentorDept || menteeDept === mentorDept) continue
    // Dedup: one edge per (mentorDept, menteeDept) pair
    const key = `${mentorDept}->${menteeDept}`
    if (seenMentorEdge.has(key)) continue
    seenMentorEdge.add(key)
    rfEdges.push({
      id: `mentor-${key}`,
      source: `dept-${mentorDept}`,
      target: `dept-${menteeDept}`,
      type: 'smoothstep',
      style: {
        stroke: '#a855f7',
        strokeWidth: 1.5,
        opacity: 0.4,
        strokeDasharray: '6 4',
      },
    } as Edge)
  }

  return { rfNodes, rfEdges }
}

