// ─── Types ──────────────────────────────────────────────────────────────────

interface TestResult {
  id: string
  agent: string
  agentName: string
  prompt: string
  output: string
  duration: number
  status: 'success' | 'error'
  timestamp: Date
}

interface PlaygroundSettings {
  timeoutMs: number
  customInstructions: string
  outputMode: 'markdown' | 'raw'
}

interface PromptTemplate {
  id: string
  name: string
  prompt: string
  agentName: string
}

interface ActivityEntry {
  message: string
  time: number
}

const STORAGE_KEY = 'polyglot:playground-history'
const SETTINGS_KEY = 'polyglot:playground-settings'
const SESSION_KEY = 'polyglot:playground-session'
const TEMPLATES_KEY = 'polyglot:playground-templates'

const DEFAULT_SETTINGS: PlaygroundSettings = {
  timeoutMs: 120000,
  customInstructions: '',
  outputMode: 'markdown',
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function loadPersistedHistory(): TestResult[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    return parsed.map((r: TestResult) => ({ ...r, timestamp: new Date(r.timestamp) }))
  } catch { return [] }
}

function loadPersistedSettings(): PlaygroundSettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY)
    if (!raw) return DEFAULT_SETTINGS
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch { return DEFAULT_SETTINGS }
}

function loadPersistedSession(): { selectedAgent: string; prompt: string; output: string } {
  try {
    const raw = localStorage.getItem(SESSION_KEY)
    if (!raw) return { selectedAgent: '', prompt: '', output: '' }
    return JSON.parse(raw)
  } catch { return { selectedAgent: '', prompt: '', output: '' } }
}

function loadPersistedTemplates(): PromptTemplate[] {
  try {
    const raw = localStorage.getItem(TEMPLATES_KEY)
    if (!raw) return []
    return JSON.parse(raw)
  } catch { return [] }
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`
  const min = Math.floor(ms / 60000)
  const sec = ((ms % 60000) / 1000).toFixed(0)
  return `${min}m ${sec}s`
}

function formatTime(date: Date): string {
  const now = new Date()
  const time = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
  if (date.toDateString() === now.toDateString()) return time
  const yesterday = new Date(now)
  yesterday.setDate(yesterday.getDate() - 1)
  if (date.toDateString() === yesterday.toDateString()) return `Yesterday ${time}`
  return `${date.toLocaleDateString([], { month: 'short', day: 'numeric' })} ${time}`
}

function toHistoryItem(r: TestResult): PlaygroundHistoryItem {
  return { ...r, timestamp: r.timestamp.toISOString() }
}

