async function request<T>(
  path: string,
  options?: RequestInit & { timeoutMs?: number; signal?: AbortSignal },
): Promise<T> {
  const { timeoutMs = 8000, signal: externalSignal, ...rest } = options ?? {}
  const controller = new AbortController()
  const tid = setTimeout(() => controller.abort(), timeoutMs)
  const signal = externalSignal
    ? (AbortSignal as unknown as { any: (sigs: AbortSignal[]) => AbortSignal }).any(
        [externalSignal, controller.signal],
      )
    : controller.signal
  try {
    const res = await fetch(`${BASE}${path}`, {
      headers: { 'Content-Type': 'application/json' },
      ...rest,
      signal,
    })
    clearTimeout(tid)
    if (!res.ok) {
      const data = await res.json().catch(() => ({ error: `HTTP ${res.status}` }))
      throw new Error(data.error || `API error: ${res.status}`)
    }
    return res.json()
  } catch (err) {
    clearTimeout(tid)
    throw err
  }
}

async function requestWithRetry<T>(path: string, options?: RequestInit): Promise<T> {
  try {
    return await request<T>(path, options)
  } catch (err) {
    if (err instanceof Error && err.name === 'AbortError') throw err
    await new Promise(r => setTimeout(r, 500))
    return request<T>(path, options)
  }
}

