import { useEffect, useRef, useState } from 'react'
import { CheckCircle, AlertCircle, Undo2, X } from 'lucide-react'

export type ToastType = 'success' | 'error' | 'warn'

export interface ToastAction {
  label: string
  onClick: () => void | Promise<void>
}

export interface ToastMessage {
  id: number
  type: ToastType
  message: string
  action?: ToastAction
  duration?: number
}

export interface ToastOptions {
  action?: ToastAction
  /** Override auto-dismiss duration (ms). Default 4000, action toasts default 6000. */
  duration?: number
}

let _nextId = 1
const _listeners: Array<(t: ToastMessage) => void> = []

export function toast(type: ToastType, message: string, opts: ToastOptions = {}) {
  const msg: ToastMessage = {
    id: _nextId++,
    type,
    message,
    action: opts.action,
    duration: opts.duration ?? (opts.action ? 6000 : 4000),
  }
  _listeners.forEach(fn => fn(msg))
  return msg.id
}

export function ToastContainer() {
  const [toasts, setToasts] = useState<ToastMessage[]>([])
  const timersRef = useRef<Map<number, ReturnType<typeof setTimeout>>>(new Map())

  const dismiss = (id: number) => {
    setToasts(prev => prev.filter(x => x.id !== id))
    const t = timersRef.current.get(id)
    if (t) clearTimeout(t)
    timersRef.current.delete(id)
  }

  useEffect(() => {
    const handler = (t: ToastMessage) => {
      setToasts(prev => [...prev, t])
      const timer = setTimeout(() => {
        setToasts(prev => prev.filter(x => x.id !== t.id))
        timersRef.current.delete(t.id)
      }, t.duration ?? 4000)
      timersRef.current.set(t.id, timer)
    }
    _listeners.push(handler)
    return () => {
      const idx = _listeners.indexOf(handler)
      if (idx >= 0) _listeners.splice(idx, 1)
      timersRef.current.forEach(clearTimeout)
      timersRef.current.clear()
    }
  }, [])

  const handleAction = async (t: ToastMessage) => {
    if (!t.action) return
    dismiss(t.id)
    try {
      await t.action.onClick()
    } catch {
      // The action handler is responsible for its own error toast.
    }
  }

  if (toasts.length === 0) return null

  return (
    <div className="fixed bottom-24 right-6 z-[100] flex flex-col gap-2 pointer-events-none">
      {toasts.map(t => (
        <div
          key={t.id}
          className={`flex items-center gap-2.5 px-4 py-3 rounded-xl shadow-lg text-sm font-medium pointer-events-auto transition-all ${
            t.type === 'success'
              ? 'bg-green-muted border border-green/30 text-green'
              : t.type === 'warn'
              ? 'bg-amber-500/10 border border-amber-500/30 text-amber-400'
              : 'bg-red-muted border border-red/30 text-red'
          }`}
        >
          {t.type === 'success'
            ? <CheckCircle className="w-4 h-4 shrink-0" />
            : <AlertCircle className="w-4 h-4 shrink-0" />}
          <span>{t.message}</span>
          {t.action && (
            <button
              onClick={() => handleAction(t)}
              className="ml-2 flex items-center gap-1 px-2 py-0.5 rounded-md bg-white/15 hover:bg-white/25 text-current font-semibold text-[12px] transition-colors"
            >
              <Undo2 className="w-3 h-3" />
              {t.action.label}
            </button>
          )}
          <button
            onClick={() => dismiss(t.id)}
            className="ml-1 opacity-60 hover:opacity-100 transition-opacity"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      ))}
    </div>
  )
}

